"""Evidence and exact-scope checkpoint for the substantive p35–p54 review."""
from pathlib import Path
from datetime import datetime,timezone
import re,json,hashlib,sys,xml.etree.ElementTree as E
W=Path(__file__).resolve().parent;D=W/'sources/review-p35-p54';IDS=['p'+str(i) for i in range(35,55)]
def save(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def sht(t):return hashlib.sha256(t.encode()).hexdigest()
def blocks(s):return {m[1]:m[2].strip() for m in re.finditer(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',s,re.S|re.M)}
notes={
'p35':('retained','Alle fünf Absätze geprüft: qualifizierte Ausstellung, sechs Monate ab erstmaliger Zurschaustellung, Bekanntmachungswege, zwei getrennte Zweimonatsfristen, Nachweisverwirkung und keine Verlängerung der §-34-Frist. Fiktives Messebeispiel bleibt sachgerecht; bloßer Bekanntheitsgrad einer Messe genügt nicht.'),
'p36':('retained','Alle fünf Absätze sowie vier Prüfgegenstände und drei unterschiedliche Säumnisfolgen gelesen: Rangverschiebung/Rücknahmefiktion, Klassenreihenfolge und Teilrücknahme sowie Zurückweisung bei sonstigen Mängeln oder fehlender Inhaberfähigkeit. Keine unbedingte Wahrung des ursprünglichen Rangs behauptet.'),
'p37':('corrected','Sechs Absätze geprüft. Rangverschiebung unter Verlust auch beanspruchter Priorität ausdrücklich ergänzt. Begrenzte Amtsprüfung notorischer Marken, Ersichtlichkeit, Teilzurückweisung, Drittbemerkungen und fehlende Beteiligtenstellung getrennt. Beispiel nach Waren differenziert.'),
'p38':('retained','Antragserfordernis und Beschleunigung beider Prüfungen nach §§ 36 und 37 geprüft. Keine Herabsetzung der Schutzvoraussetzungen, keine Garantie gegen ältere Rechte und keine Verkürzung der Widerspruchsfrist behauptet; kein ungesicherter Gebührenbetrag.'),
'p39':('retained','Beide Absätze gegen Anmeldung, Beschränkung und Teilung abgeglichen. Rücknahme/Einschränkung von Berichtigung offensichtlicher Fehler unterschieden; Austausch des Zeichens oder zusätzliche Waren nicht als bloße Korrektur unter altem Rang behandelt.'),
'p40':('retained','Beide Absätze geprüft: Erklärung und Warenzuordnung, Rangwahrung jeder Teilanmeldung, Gebühr binnen drei Monaten nach Zugang, Rücknahmefiktion nur für abgetrennte Anmeldung und Unwiderruflichkeit. Zutreffende Abgrenzung zu § 46 bleibt erhalten.'),
'p41':('retained','Drei Absätze einschließlich Übermittlungsschranke § 62 Abs. 4 gelesen. Eintragungsvoraussetzungen, Entstehung nach § 4 Nr. 1, amtliche Veröffentlichung als Fristauslöser und Begrenzung elektronischer Weitergabe sind zutreffend erklärt. Private Meldung nicht mit amtlicher Veröffentlichung gleichgesetzt.'),
'p42':('corrected','Alle vier Absätze und fünf Widerspruchsgründe geprüft. Abschließenden Katalog erläutert, Namens-/Urheberrechte nicht pauschal aufgenommen. Seit 16.01.2026 geltende Berechtigtenstellung in Abs. 3 nach Art. 5 Nr. 9 des Gesetzes 2026 I Nr. 9 benannt. Amtlichen Veröffentlichungstag, Bündelung und beiderseitigen Einigungsantrag getrennt.'),
'p43':('corrected','Vier Absätze geprüft. Historischen Fünfjahreszeitraum, Einrede, Nachweismittel und § 26 Abs. 5 konkretisiert. Beispiel trennt benutzten Schutzumfang der älteren Marke von anschließend möglicher Warenähnlichkeit; keine automatische Beschränkung der Kollision auf identische Waren. Wirkung nach § 52 Abs. 2/3 erläutert; Altverfahren nach § 158 Abs. 5 abgegrenzt.'),
'p44':('retained','Alle drei Absätze gelesen: Klage gegen Widersprechenden trotz Löschung nach § 43, sechs Monate ab Unanfechtbarkeit und Rangwahrung bei Eintragung nach günstiger Entscheidung. Keine Verwechslung mit Amtsbeschwerde oder automatische Hemmung anderer Rechtsmittelfristen.'),
'p45':('retained','Beide Absätze geprüft: Antrag/Amtsweg, Fehlerarten, erneute Veröffentlichung bei veröffentlichter Eintragung und entsprechende Berichtigung bloßer Veröffentlichungen. Beispiel bleibt auf klaren Übertragungsfehler beschränkt; kein Logoaustausch als Registerkorrektur.'),
'p46':('corrected','Alle drei Absätze geprüft. Unpräzisen Gebührenbeginn nach Erklärung auf Zugang der Teilungserklärung berichtigt. Abgelaufene Widerspruchsfrist, konkrete Reichweite anhängiger Angriffe und Unwiderruflichkeit erläutert; Verzichtsfiktion von Anmeldungsteilung getrennt.'),
'p47':('corrected','Acht Absätze gelesen. Antrag durch ermächtigte Person, Zahlung als Antrag, Klassengebühren ab vierter Klasse, gezielte Teilverlängerung gegenüber Auffangreihenfolge, Mindestvorabinformation und beide Zeitfenster präzisiert. Übergang nach § 159 knüpft an Eintragung vor 14.01.2019, nicht pauschal ältere Anmeldung an. Gebührenübergang getrennt.'),
'p48':('corrected','Beide Absätze und § 30 Abs. 6 abgeglichen. Verzichtsumfang und fehlende automatische Rückwirkung erklärt. Löschung der Marke mit Zustimmung nach § 48 Abs. 2 von Löschung des Lizenzvermerks nach § 30 Abs. 6 getrennt; Zustimmung nicht ohne Weiteres austauschbar.'),
'p49':('corrected','Alle drei Absätze und vier Sätze des Abs. 1 gelesen. Beginn der Benutzungszeit, berechtigte Gründe, Voraussetzungen der taktischen Wiederaufnahme und exakter Übergang zur Klage ergänzt: drei Monate nach Zustellung der Mitteilung nach § 53 Abs. 4. Abgrenzung zur Fortsetzungsgebühr und Sperre nach § 55 Abs. 1, Warenbegrenzung und zeitliche Wirkungen aufgenommen.'),
'p50':('corrected','Vier Absätze samt Nummernbereichen und Zeitpunkten geprüft. Ursprünglichen Mangel, Fortbestehen, Verkehrsdurchsetzung bis Antrag, Zehnjahresgrenze und amtswegige Zweijahresregel getrennt. Nivea-Blau vollständig amtlich gegengeprüft; nur methodische Aussagen/Untergruppen als heutige Auslegungshilfe, historische Heilungsregel ausdrücklich begrenzt. § 158 Abs. 8 genannt.'),
'p51':('corrected','Fünf Absätze geprüft. Durch Art. 5 Nr. 10 des Gesetzes 2026 I Nr. 9 ergänzte Berechtigtenstellung berücksichtigt. Duldung genau für bezeichnete Rechtsarten, Anmeldung in Bösgläubigkeit und Zustimmung zur Eintragung unterschieden. Historische Bekanntheit, Verfalls-/Nichtigkeitsreife und Kennzeichnungskraft sowie Teilnichtigkeit erläutert.'),
'p52':('corrected','Drei Absätze und beide Nummern geprüft. Früherer Verfallszeitpunkt nur auf Antrag und Festsetzung. Bei Verletzungsentscheidungen Rechtskraft UND Vollstreckung vor Bestandsentscheidung erforderlich; Verträge nur soweit vorher erfüllt. Schadensersatz, Bereicherung und Billigkeitsrückerstattung getrennt; offene Raten nicht pauschal geschützt.'),
'p53':('corrected','Alle sieben Absätze gelesen. Sicherheitsleistung nach PatG § 81 Abs. 6 und Rechtsnachfolge nach ZPO § 325 Abs. 1 tatsächlich nachgelesen. Streitgegenstandssperren, Antragsbefugnis, Zustellung, Widerspruch und Fortsetzungsgebühr getrennt. Benutzung vor Antrag, bei späterem Ablauf vor Entscheidung und zusätzlicher historischer Bestand einzeln erläutert; Abs. 7 und entsprechende ZPO-Eintrittsregeln geprüft.'),
'p54':('corrected','Beide Absätze und zwei Beitrittsalternativen geprüft: identische Marke, Glaubhaftmachung, keine unanfechtbare Bestandsentscheidung, drei Monate ab Verletzungsverfahren oder Zugang der Aufforderung. Verweisung auf § 53 Abs. 1–3 und Beschwerdebeteiligtenstellung konkretisiert; Abmahnung schafft nicht automatisch eigenes älteres Recht.')}
baseline=json.loads((D/'commentary-baseline.json').read_text());before=baseline['commentary'];now=datetime.now(timezone.utc).isoformat();current={}
for p in sorted((W/'commentary').glob('*.md')):current.update(blocks(p.read_text()))
assert set(current)==set(before) and set(IDS)==set(notes)
changed=[i for i in current if current[i]!=before[i]];assert len(changed)==12 and set(changed)<=set(IDS)
for i in IDS:assert (i in changed)==(notes[i][0]=='corrected')
u={x['id']:x for x in map(json.loads,(W/'units.jsonl').read_text().splitlines())};r=E.parse(D/'markeng.xml').getroot();ns={n.attrib['doknr']:n for n in r.findall('norm')};compact=lambda x:re.sub(r'\s+','',x)
findings=[]
for i in IDS:
 x=u[i];n=ns[x['xml_doknr']];assert compact(x['text'])==compact(''.join(n.find('textdaten/text/Content').itertext()))
 findings.append(dict(id=i,label=x['label'],outcome=notes[i][0],finding=notes[i][1],resolved=True,source_xml_doknr=x['xml_doknr'],statutory_text_sha256=sht(x['text']),commentary_before_sha256=sht(before[i]),commentary_after_sha256=sht(current[i])))
c=E.parse(D/'nivea.xml').getroot();local=compact((D/'nivea-local.md').read_text());count=0
for tag in ['tenor','gruende']:
 for p in c.findall('.//'+tag+'//p'):
  text=''.join(p.itertext()).strip()
  if text:assert compact(text) in local;count+=1
assert count>=47
